sources.BulletinDetails.ets:
@Component
export struct BulletinDetails {
  title: string = ''
  subtitle: string = ''
  markup: string = ''

  build() {
    Column() {
      Text(this.title)
      Text(this.subtitle)
      Text(this.cleanedBody())
    }
  }

  cleanedBody(): string {
    return this.markup
      .replace('<p>', '')
      .replace('</p>', '')
  }
}

sources.BulletinDetailsStore.ets:
export class BulletinDetailsStore {
  title: string = ''
  saveDetails() {
    this.title = this.title.trim()
    console.info('save bulletin details markup title')
  }
}

